pub fn sanitize_inline(text: &str) -> Cow<'_, str> {
    if text.chars().any(char::is_control) {
        Cow::Owned(text.chars().filter(|ch| !ch.is_control()).collect())
    } else {
        Cow::Borrowed(text)
    }
